  ('pages.blog.optimiser-remuneration-portage-salarial.auto.heading.g6h7pq', '/blog/optimiser-remuneration-portage-salarial', 'heading', 'Documenter ses frais professionnels'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.heading.y07sgc', '/blog/optimiser-remuneration-portage-salarial', 'heading', 'Besoin d''un accompagnement personnalisé ?'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.18ahffj', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Comment optimiser sa rémunération en portage salarial ?'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1dbhcig', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Votre TJM doit refléter votre expertise, votre rareté sur le marché et la valeur livrée au client. C''est particulièrement vrai pour les profils cyber, data, DevOps, cloud et pilotage IT, où l''expérience et le niveau de responsabilité changent fortement le prix de mission.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1fandyv', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'TJM, jours facturés, frais professionnels et accompagnement : les leviers à suivre pour mieux piloter votre rémunération nette.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1robbm7', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Partager cet article :'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.4jz01', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Matériel informatique, logiciels, déplacements, repas, téléphonie ou abonnements peuvent entrer dans la discussion lorsqu''ils sont liés à l''activité et justifiés. The Porters doit valider les modalités exactes selon votre situation.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.qrkykr', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Une question ?'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.t30x3f', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Optimiser sa rémunération en portage salarial commence par une lecture claire du chiffre d''affaires facturé, des frais professionnels, des charges et du rythme de mission.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.u2k7no', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Nos conseillers sont à votre disposition pour étudier votre projet et répondre à vos questions sur le portage salarial.'),
