  ('pages.consultants.auto.paragraph.18ahffj', '/consultants', 'paragraph', 'Votre quotidien'),
  ('pages.consultants.auto.paragraph.18ldtpn', '/consultants', 'paragraph', 'Nous reprenons votre mission, votre TJM, vos frais et votre simulation. Le contrat de travail et le contrat de prestation sont établis avant le démarrage.'),
  ('pages.consultants.auto.paragraph.193cqcp', '/consultants', 'paragraph', 'Ce que vous gardez'),
  ('pages.consultants.auto.paragraph.1b3pvb9', '/consultants', 'paragraph', 'Mission en France ou à l’étranger, pour un client français ou étranger, en télétravail ou sur site.'),
  ('pages.consultants.auto.paragraph.1bpp3an', '/consultants', 'paragraph', 'Vous pouvez vous constituer votre propre clientèle et en rester pleinement responsable. Nous vous proposons aussi des missions issues de nos partenaires.'),
