  ('pages.consultants.auto.paragraph.1e907ml', '/consultants', 'paragraph', 'Chronologie'),
  ('pages.consultants.auto.paragraph.1f7fpoy', '/consultants', 'paragraph', 'Vous pouvez mettre une part de votre rémunération brute de côté pour lisser une paie, financer des congés ou provisionner une fin de contrat.'),
