  ('pages.consultants.auto.paragraph.1k8zyd3', '/consultants', 'paragraph', 'Les modalités de départ suivent le droit du travail. Nous préparons les documents de fin de contrat et vous expliquons les étapes applicables à votre situation.'),
  ('pages.consultants.auto.paragraph.1kao9sa', '/consultants', 'paragraph', 'Avec un emploi salarié, sous réserve de l’accord de votre employeur et d’un maximum de 48 heures hebdomadaires cumulées. Ou avec une retraite.'),
  ('pages.consultants.auto.paragraph.1kx3w6b', '/consultants', 'paragraph', 'Cybersécurité, GRC et gouvernance'),
