  ('pages.consultants.auto.paragraph.1nzigs2', '/consultants', 'paragraph', 'Ce que The Porters gère'),
  ('pages.consultants.auto.paragraph.1rvb5sc', '/consultants', 'paragraph', 'Ni chez votre client, ni chez The Porters. Vous êtes salarié sur la forme, autonome sur le fond.'),
  ('pages.consultants.auto.paragraph.4ouu68', '/consultants', 'paragraph', 'Vous cotisez chaque mois à l’assurance chômage et conservez vos droits, comme tout salarié.'),
