  ('pages.consultants.auto.paragraph.f0xscj', '/consultants', 'paragraph', 'Vous gardez vos missions, votre TJM et votre organisation. Nous cadrons les contrats, la facturation, la paie et le suivi administratif.'),
  ('pages.consultants.auto.paragraph.jwielf', '/consultants', 'paragraph', 'Le statut cadre vous permet de cotiser au régime général et à la retraite complémentaire.'),
  ('pages.consultants.auto.paragraph.m29l4s', '/consultants', 'paragraph', 'Le simulateur répond en quelques minutes. Un conseiller reprend ensuite vos hypothèses avec vous.'),
  ('pages.consultants.auto.paragraph.pc2pk8', '/consultants', 'paragraph', 'Vous déclarez votre activité et vos frais professionnels. Nous facturons le client, établissons votre bulletin de paie et traitons les déclarations sociales.'),
  ('pages.consultants.auto.paragraph.qrkykr', '/consultants', 'paragraph', 'Une question ?'),
