  ('pages.mentions-legales.auto.list_item.1tkm0mp', '/mentions-legales', 'list_item', 'Site web : <a href="https://www.cloudflare.com/" target="_blank" rel="noopener noreferrer">www.cloudflare.com</a>'),
  ('pages.mentions-legales.auto.list_item.6458zl', '/mentions-legales', 'list_item', 'SIRET du siège : 828 954 735 00043'),
  ('pages.mentions-legales.auto.list_item.d47o88', '/mentions-legales', 'list_item', 'Numéro de TVA intracommunautaire : FR42 828 954 735'),
