  ('pages.parrainage.auto.list_item.1smnah4', '/parrainage', 'list_item', '<span class="w-1.5 h-1.5 rounded-full bg-porters-gold mt-2 shrink-0"></span>Aucune coordonnée transmise sans accord'),
  ('pages.parrainage.auto.list_item.2tdmld', '/parrainage', 'list_item', '<span class="w-1.5 h-1.5 rounded-full bg-porters-gold mt-2 shrink-0"></span>Éligibilité confirmée par l’équipe The Porters'),
  ('pages.parrainage.auto.list_item.e3ycfu', '/parrainage', 'list_item', '<span class="w-1.5 h-1.5 rounded-full bg-porters-gold mt-2 shrink-0"></span>Conditions communiquées avant toute mise en relation'),
  ('pages.parrainage.auto.paragraph.18ahffj', '/parrainage', 'paragraph', 'Parrainage'),
  ('pages.parrainage.auto.paragraph.1dn64v7', '/parrainage', 'paragraph', 'Parlez de nous à un consultant indépendant ou à une entreprise.'),
  ('pages.parrainage.auto.paragraph.1oz04k7', '/parrainage', 'paragraph', 'Programme soumis aux conditions d''éligibilité communiquées lors de la mise en relation.'),
  ('pages.parrainage.auto.paragraph.e0jvi5', '/parrainage', 'paragraph', 'Vous et la personne cooptée recevez une prime nette d’impôts. Le montant et l’éligibilité vous sont précisés avant toute mise en relation.'),
  ('pages.parrainage.auto.paragraph.m7k6kn', '/parrainage', 'paragraph', 'Un consultant qui hésite sur son statut, ou une entreprise qui cherche un profil IT. Présentez-nous la personne : nous qualifions le besoin, et vous touchez une prime nette d’impôts si la mise en relation aboutit.'),
  ('pages.parrainage.auto.paragraph.pyzpvb', '/parrainage', 'paragraph', 'Expliquez-nous le contexte. Nous vous indiquons la marche à suivre avant tout partage de coordonnées.'),
  ('pages.parrainage.auto.paragraph.qrkykr', '/parrainage', 'paragraph', 'Une question ?'),
  ('pages.parrainage.auto.paragraph.sbfhgg', '/parrainage', 'paragraph', 'La personne nous contacte de votre part, ou vous nous transmettez ses coordonnées — avec son accord.'),
  ('pages.parrainage.auto.paragraph.w5nn90', '/parrainage', 'paragraph', 'Programme de parrainage'),
