  ('pages.portage-salarial.auto.paragraph.1264m40', '/portage-salarial', 'paragraph', 'Contrat, facturation, paie et déclarations.'),
  ('pages.portage-salarial.auto.paragraph.13i353e', '/portage-salarial', 'paragraph', 'Vous trouvez vos clients, négociez votre TJM et pilotez votre intervention.'),
  ('pages.portage-salarial.auto.paragraph.16622un', '/portage-salarial', 'paragraph', 'The Porters facture l’entreprise cliente. Le montant disponible, après les éléments applicables à votre situation, finance votre rémunération et les charges associées.'),
  ('pages.portage-salarial.auto.paragraph.16zzx9b', '/portage-salarial', 'paragraph', 'Chaque mois'),
