  ('pages.portage-salarial.auto.paragraph.1bx0ylt', '/portage-salarial', 'paragraph', 'Relation tripartite'),
  ('pages.portage-salarial.auto.paragraph.1cr4qj0', '/portage-salarial', 'paragraph', 'Contrat de prestation, facturation, paie et déclarations passent chez The Porters.'),
  ('pages.portage-salarial.auto.paragraph.1e907ml', '/portage-salarial', 'paragraph', 'La répartition est simple'),
  ('pages.portage-salarial.auto.paragraph.1hkia6c', '/portage-salarial', 'paragraph', 'Vous réalisez la mission pour l’entreprise cliente. The Porters signe le contrat de prestation, vous emploie et prend en charge le cadre administratif.'),
  ('pages.portage-salarial.auto.paragraph.1id3tdl', '/portage-salarial', 'paragraph', 'Portage salarial'),
