  ('pages.portage-salarial.auto.paragraph.1wqii8s', '/portage-salarial', 'paragraph', 'annoncés avant signature'),
  ('pages.portage-salarial.auto.paragraph.1ygc6qv', '/portage-salarial', 'paragraph', 'Contrat de prestation'),
  ('pages.portage-salarial.auto.paragraph.5ksvxe', '/portage-salarial', 'paragraph', 'Ils couvrent notamment le cadre contractuel, la facturation, la paie, le suivi administratif, la responsabilité civile professionnelle et la garantie financière.'),
  ('pages.portage-salarial.auto.paragraph.7hnjwa', '/portage-salarial', 'paragraph', 'L''entreprise cliente'),
