  ('pages.qui-sommes-nous.auto.paragraph.1dsgqdy', '/qui-sommes-nous', 'paragraph', 'Les engagements, les accès et les contraintes du client sont rendus lisibles.'),
  ('pages.qui-sommes-nous.auto.paragraph.1du49on', '/qui-sommes-nous', 'paragraph', 'The Porters porte les consultants indépendants qui interviennent sur les enjeux de gouvernance, de conformité, de prévention, de détection et de réponse aux incidents de sécurité. Ces experts aident les entreprises à mieux identifier leurs risques, sécuriser leurs infrastructures, protéger leurs actifs critiques et répondre aux exigences réglementaires.'),
  ('pages.qui-sommes-nous.auto.paragraph.1du619x', '/qui-sommes-nous', 'paragraph', 'Ces consultants aident les organisations à fiabiliser leurs données, industrialiser leurs infrastructures, améliorer leur prise de décision et intégrer des solutions d’intelligence artificielle dans leurs processus, leurs produits et leurs outils internes.'),
  ('pages.qui-sommes-nous.auto.paragraph.1dwo0t9', '/qui-sommes-nous', 'paragraph', 'Domaine sélectionné'),
