  ('pages.qui-sommes-nous.auto.paragraph.qj4syn', '/qui-sommes-nous', 'paragraph', 'Leurs missions ne se limitent pas à l’application d’une méthode. Elles consistent également à accompagner le changement, faire évoluer les pratiques managériales, résoudre les blocages organisationnels et créer une dynamique d’amélioration continue.'),
  ('pages.qui-sommes-nous.auto.paragraph.qn4k1c', '/qui-sommes-nous', 'paragraph', 'Mise en production et suivi des performances'),
  ('pages.qui-sommes-nous.auto.paragraph.qnovga', '/qui-sommes-nous', 'paragraph', 'Delivery Manager'),
  ('pages.qui-sommes-nous.auto.paragraph.qq817t', '/qui-sommes-nous', 'paragraph', 'Les missions en cybersécurité demandent souvent une forte expertise, une grande autonomie et une capacité à intervenir rapidement dans des contextes sensibles. Le portage salarial permet au consultant de conserver son indépendance tout en bénéficiant d’un cadre contractuel et administratif structuré.'),
  ('pages.qui-sommes-nous.auto.paragraph.qrkykr', '/qui-sommes-nous', 'paragraph', 'Une question ?'),
  ('pages.qui-sommes-nous.auto.paragraph.qs9u1u', '/qui-sommes-nous', 'paragraph', 'Data &amp; IA'),
  ('pages.qui-sommes-nous.auto.paragraph.qta42s', '/qui-sommes-nous', 'paragraph', 'Pour relier conseil et delivery sur les enjeux Data, IA, Cloud et cybersécurité.'),
  ('pages.qui-sommes-nous.auto.paragraph.r18dee', '/qui-sommes-nous', 'paragraph', 'Leurs missions couvrent les environnements cloud publics, privés ou hybrides, les chaînes d’intégration et de déploiement continus, la conteneurisation, l’observabilité, la résilience, la sécurité et l’optimisation des coûts d’infrastructure.'),
  ('pages.qui-sommes-nous.auto.paragraph.r29nm2', '/qui-sommes-nous', 'paragraph', 'Les prestations qui touchent aux interfaces s’appuient sur le RGAA et les recommandations WCAG dès la conception.'),
  ('pages.qui-sommes-nous.auto.paragraph.r9bp69', '/qui-sommes-nous', 'paragraph', 'Note de cadrage'),
  ('pages.qui-sommes-nous.auto.paragraph.rhytel', '/qui-sommes-nous', 'paragraph', 'Protection sociale du salarié porté'),
  ('pages.qui-sommes-nous.auto.paragraph.rmydci', '/qui-sommes-nous', 'paragraph', 'Generative AI'),
  ('pages.qui-sommes-nous.auto.paragraph.rp6j35', '/qui-sommes-nous', 'paragraph', 'RSSI'),
  ('pages.qui-sommes-nous.auto.paragraph.ruxonj', '/qui-sommes-nous', 'paragraph', 'Design Thinking'),
  ('pages.qui-sommes-nous.auto.paragraph.rv6bkt', '/qui-sommes-nous', 'paragraph', 'Les professionnels du produit et du projet occupent fréquemment des rôles stratégiques au sein d’équipes clientes pendant plusieurs mois. Le portage salarial leur permet d’exercer en autonomie tout en bénéficiant d’un statut structuré et d’une gestion simplifiée.'),
  ('pages.qui-sommes-nous.auto.paragraph.s9vp9p', '/qui-sommes-nous', 'paragraph', 'Notre vision'),
  ('pages.qui-sommes-nous.auto.paragraph.sc04fv', '/qui-sommes-nous', 'paragraph', 'AWS'),
  ('pages.qui-sommes-nous.auto.paragraph.sc1wm8', '/qui-sommes-nous', 'paragraph', 'Consultant IA générative'),
  ('pages.qui-sommes-nous.auto.paragraph.sg6in5', '/qui-sommes-nous', 'paragraph', 'L’approche en bref'),
  ('pages.qui-sommes-nous.auto.paragraph.su0iri', '/qui-sommes-nous', 'paragraph', 'Gestion administrative de l’activité'),
  ('pages.qui-sommes-nous.auto.paragraph.tw4h7q', '/qui-sommes-nous', 'paragraph', 'Supervision de la réalisation, organisation des mises en production, suivi des résultats et amélioration continue du produit ou du service.'),
  ('pages.qui-sommes-nous.auto.paragraph.u2k7no', '/qui-sommes-nous', 'paragraph', 'The Porters · Notre rôle'),
  ('pages.qui-sommes-nous.auto.paragraph.uch92o', '/qui-sommes-nous', 'paragraph', 'L’approche en bref'),
  ('pages.qui-sommes-nous.auto.paragraph.ueor2s', '/qui-sommes-nous', 'paragraph', 'Release Engineer'),
  ('pages.qui-sommes-nous.auto.paragraph.uezw8c', '/qui-sommes-nous', 'paragraph', 'Les consultants en agilité interviennent souvent dans des environnements de transformation, sur des périodes de plusieurs mois et auprès de nombreuses parties prenantes. Le portage salarial leur offre un cadre professionnel adapté sans limiter leur autonomie dans la conduite de leurs missions.'),
  ('pages.qui-sommes-nous.auto.paragraph.uh3pdw', '/qui-sommes-nous', 'paragraph', 'Google Cloud Platform'),
  ('pages.qui-sommes-nous.auto.paragraph.uiyqiy', '/qui-sommes-nous', 'paragraph', 'Domaine sélectionné'),
  ('pages.qui-sommes-nous.auto.paragraph.ukdmv3', '/qui-sommes-nous', 'paragraph', 'Release Train Engineer'),
  ('pages.qui-sommes-nous.auto.paragraph.ulh3yi', '/qui-sommes-nous', 'paragraph', 'Concevoir des infrastructures plus agiles, plus fiables et plus performantes pour accélérer la transformation technologique des organisations.'),
  ('pages.qui-sommes-nous.auto.paragraph.uvb34i', '/qui-sommes-nous', 'paragraph', 'Solutions d’intelligence artificielle intégrées'),
