  ('pages.qui-sommes-nous.auto.paragraph.xewkaa', '/qui-sommes-nous', 'paragraph', 'OKR'),
  ('pages.qui-sommes-nous.auto.paragraph.xkvgg', '/qui-sommes-nous', 'paragraph', 'Pilotage de projet et coordination'),
  ('pages.qui-sommes-nous.auto.paragraph.xlopst', '/qui-sommes-nous', 'paragraph', 'Microsoft Azure'),
  ('pages.qui-sommes-nous.auto.paragraph.xnfv1k', '/qui-sommes-nous', 'paragraph', 'L’approche KwickStart traite le Cloud comme une trajectoire : conseil sur mesure, intégration flexible, optimisation des infrastructures et suivi de la performance.'),
  ('pages.qui-sommes-nous.auto.paragraph.xut6t4', '/qui-sommes-nous', 'paragraph', 'Backlog priorisé'),
  ('pages.qui-sommes-nous.auto.paragraph.xxeyen', '/qui-sommes-nous', 'paragraph', 'Nos valeurs'),
  ('pages.qui-sommes-nous.auto.paragraph.y9dn5c', '/qui-sommes-nous', 'paragraph', 'Nous partons du métier, du niveau de responsabilité et de la réalité de la mission pour proposer un cadre pertinent.'),
  ('pages.qui-sommes-nous.auto.paragraph.ycqb9e', '/qui-sommes-nous', 'paragraph', 'Gouvernance et stratégie de sécurité'),
  ('pages.qui-sommes-nous.auto.paragraph.ygivuo', '/qui-sommes-nous', 'paragraph', 'Kanban'),
  ('pages.qui-sommes-nous.auto.paragraph.ynnxij', '/qui-sommes-nous', 'paragraph', 'Design Thinking'),
  ('pages.qui-sommes-nous.auto.paragraph.yt1da6', '/qui-sommes-nous', 'paragraph', 'Gestion des contrats de prestation'),
  ('pages.qui-sommes-nous.auto.paragraph.yzyyic', '/qui-sommes-nous', 'paragraph', 'Les missions peuvent concerner aussi bien la définition d’une stratégie de cybersécurité que la sécurisation opérationnelle des environnements cloud, des identités, des applications, des réseaux ou des données sensibles.'),
  ('pages.qui-sommes-nous.auto.paragraph.z69vd6', '/qui-sommes-nous', 'paragraph', 'Conseil stratégique et de gouvernance, assistance technique sur un périmètre défini, formation et sensibilisation des équipes aux bonnes pratiques.'),
  ('pages.qui-sommes-nous.auto.paragraph.zct6fy', '/qui-sommes-nous', 'paragraph', 'L’approche en bref'),
