  ('pages.recrutement.auto.paragraph.18ahffj', '/recrutement', 'paragraph', 'Recrutement'),
  ('pages.recrutement.auto.paragraph.19wi8nk', '/recrutement', 'paragraph', 'Une équipe réduite, où votre périmètre est visible et vos décisions comptent. Télétravail régulier possible.'),
  ('pages.recrutement.auto.paragraph.1fwvrar', '/recrutement', 'paragraph', 'Ce que vous portez, ce sur quoi vous décidez et vos perspectives sont écrits dans l’offre, pas évoqués en entretien.'),
  ('pages.recrutement.auto.paragraph.1py4uro', '/recrutement', 'paragraph', 'Retrouvez les postes ouverts et les offres mises à jour de The Porters directement sur notre espace HelloWork.'),
  ('pages.recrutement.auto.paragraph.1sve2ab', '/recrutement', 'paragraph', 'Carrières'),
  ('pages.recrutement.auto.paragraph.36ekrk', '/recrutement', 'paragraph', 'Il s’agit ici des recrutements internes de The Porters : business, recrutement, gestion. Si vous cherchez une mission en portage, c’est la page Comprendre le portage salarial.'),
